package cl.nexbyte.siger.institucional.nucleo;
import cl.nexbyte.siger.institucional.notificaciones.*;import cl.nexbyte.siger.institucional.robustez.*;
import java.nio.file.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;
class CorreosOutboxTest {
 @TempDir Path p;DatosAvisosTest x;int calls;List<TransporteCorreo.Mensaje> sent;TransporteCorreo.Resultado outcome;boolean real;
 @BeforeEach void start()throws Exception{x=new DatosAvisosTest(p);calls=0;sent=new ArrayList<>();outcome=new TransporteCorreo.Resultado("ACCEPTED_BY_GRAPH","GRAPH",202,0,null);}
 @AfterEach void end(){x.close();}
 TransporteCorreo fake(){return new TransporteCorreo(){public Resultado enviar(Mensaje m){calls++;sent.add(m);return outcome;}public boolean real(){return real;}};}
 CorreosInstitucionales mail(){return new CorreosInstitucionales(x.d.db,x.cat,x.notices,fake(),Set.of("prof.avisos@example.invalid"),x.tiempo,"campana_sintetica");}
 UUID notice(){return x.recordatorio(x.caso());}
 @Test void aceptadoNoEsEntregadoYNoSeReenviaAlRepetirNiLeer(){var id=notice();var m=mail();var r=m.enviar(x.a(x.prof),id);assertEquals("ACCEPTED_BY_GRAPH",r.estado());assertEquals("PENDIENTE_CONFIRMACION_USUARIO",r.confirmacion());x.notices.leer(x.a(x.prof),id);assertEquals(r,m.enviar(x.a(x.prof),id));assertEquals(1,calls);assertEquals("PENDIENTE_CONFIRMACION_USUARIO",m.consultar(x.a(x.prof),id).confirmacion());assertFalse(sent.getFirst().texto().contains("Descripción privada"));assertFalse(sent.getFirst().asunto().contains("Contactar"));assertTrue(sent.getFirst().asunto().contains(r.correlacion().toString()));m.confirmar(x.a(x.prof),id);assertEquals("CONFIRMADA_POR_USUARIO",m.consultar(x.a(x.prof),id).confirmacion());}
 @Test void timeoutAmbiguoPersisteYReinicioNoRepite(){var id=notice();outcome=new TransporteCorreo.Resultado("AMBIGUO","GRAPH",null,0,null);assertEquals("AMBIGUO",mail().enviar(x.a(x.prof),id).estado());x.tiempo.avanzar(400);mail().recuperar();assertEquals("AMBIGUO",mail().enviar(x.a(x.prof),id).estado());assertEquals(1,calls);}
 @Test void falloTrasRespuestaAntesDeCommitSeRecuperaComoAmbiguoSinDuplicar(){var id=notice();var broken=new CorreosInstitucionales(x.d.db,x.cat,x.notices,fake(),Set.of("prof.avisos@example.invalid"),x.tiempo,"campana_sintetica",r->{throw new IllegalStateException("FALLO_SQL_CONTROLADO");});assertThrows(IllegalStateException.class,()->broken.enviar(x.a(x.prof),id));assertEquals(1,calls);x.tiempo.avanzar(91);var restarted=mail();restarted.recuperar();assertEquals("AMBIGUO",restarted.consultar(x.a(x.prof),id).estado());restarted.enviar(x.a(x.prof),id);assertEquals(1,calls);}
 @Test void allowlistYCorreoResueltoDesdeCuentaImpidenCualquierOtroDestino(){var id=notice();var m=mail();var account=x.ids.cuentas(x.ti).stream().filter(a->a.id().equals(x.prof)).findFirst().orElseThrow();x.ids.actualizar(x.ti,x.prof,new cl.nexbyte.siger.institucional.identidad.IdentidadInstitucional.Perfil(account.nombre(),"no.autorizado@example.invalid",account.cargo(),account.unidad(),account.sede(),true,account.revision()));assertEquals("BLOQUEADO_ALLOWLIST",m.enviar(x.a(x.prof),id).estado());assertEquals(0,calls);assertTrue(x.d.db.sql.queryForList("SELECT id FROM mail_attempt").isEmpty());}
 @Test void revocacionDesactivacionYOtroFuncionarioNoUsanElOutbox(){var id=notice();assertEquals(404,assertThrows(FalloTecnico.class,()->mail().enviar(x.a(x.head),id)).status);var acc=x.ids.cuentas(x.ti).stream().filter(a->a.id().equals(x.prof)).findFirst().orElseThrow();x.ids.revocar(x.ti,x.prof,acc.asignaciones().getFirst().get("id").toString());mail().recuperar();assertEquals("SUPRIMIDO_CONTEXTO",x.d.db.sql.queryForObject("SELECT state FROM notification_outbox WHERE notification_id=?",String.class,id.toString()));assertEquals(0,calls);}
 @Test void rechazoYThrottlingTienenEstadosSeparadosYRespetanEspera(){var id=notice();outcome=new TransporteCorreo.Resultado("REINTENTABLE","GRAPH",429,120,null);assertEquals("REINTENTABLE",mail().enviar(x.a(x.prof),id).estado());assertEquals(409,assertThrows(FalloTecnico.class,()->mail().enviar(x.a(x.prof),id)).status);x.tiempo.avanzar(121);outcome=new TransporteCorreo.Resultado("RECHAZADO","GRAPH",403,0,null);assertEquals("RECHAZADO",mail().enviar(x.a(x.prof),id).estado());mail().enviar(x.a(x.prof),id);assertEquals(2,calls);}
 @Test void recordatorioObsoletoSeSuprimePeroAceptadoConservaConfirmacionHumana(){UUID c=x.caso();var id=x.recordatorio(c);var accepted=mail().enviar(x.a(x.prof),id);String task=x.d.db.sql.queryForObject("SELECT resource_id FROM institution_notification WHERE id=?",String.class,id.toString());x.tareas.estado(x.a(x.prof),UUID.randomUUID(),UUID.fromString(task),new TareasPersonales.Cambio(0,"COMPLETADA",true));assertEquals(accepted.estado(),mail().consultar(x.a(x.prof),id).estado());mail().confirmar(x.a(x.prof),id);assertEquals("CONFIRMADA_POR_USUARIO",mail().consultar(x.a(x.prof),id).confirmacion());assertEquals(1,calls);}
 @Test void campanaRealSeLimitaACuatroIntentosAunqueReinicie(){real=true;for(int i=0;i<4;i++)mail().enviar(x.a(x.prof),notice());assertEquals(4,calls);var id=notice();assertEquals(409,assertThrows(FalloTecnico.class,()->mail().enviar(x.a(x.prof),id)).status);assertEquals(4,x.d.db.sql.queryForObject("SELECT sends_started FROM mail_campaign",Integer.class));assertEquals(4,calls);}
}
